    func testConstructionMatchesActualImmutableV9ModulesAndSharedMathOrder()throws {
        let rows=try XCTUnwrap(JSONSerialization.jsonObject(with:Data(Self.sourceConstruction.utf8)) as? [[String:Any]])
        for row in rows {
            let runtime=NativeSourceAnimationRuntime(wallOriginMilliseconds:0)
            var state=(row["seed"] as! NSNumber).uint32Value,draws=0
            let graph=try NativeEndgameHintSourceGraph(message:row["message"] as! String,width:390,height:844,
                scheduler:NativeNoMovesValueScheduler(runtime),current:{true},random:{draws+=1;state=1664525 &* state &+ 1013904223;return Double(state)/4294967296})
            let letters=row["letters"] as! [[String:Any]],clouds=row["clouds"] as! [[String:Any]]
            func n(_ object:[String:Any],_ name:String)->Double {(object[name] as! NSNumber).doubleValue}
            XCTAssertEqual(draws,(row["draws"] as! NSNumber).intValue);XCTAssertEqual(state,(row["state"] as! NSNumber).uint32Value)
            XCTAssertEqual(graph.tilt,n(row,"tilt"),accuracy:1e-12)
            for (i,letter) in graph.letters.enumerated(){XCTAssertEqual(String(letter.character),letters[i]["character"] as? String);XCTAssertEqual(letter.size,n(letters[i],"size"),accuracy:1e-12)}
            for (i,c) in graph.clouds.enumerated(){
                let r=clouds[i]
                for (key,value) in [("width",c.width),("height",c.height),("x",c.x),("y",c.y),("rotation",c.rotation),("scale",c.scale),("delay",c.delay),("windDuration",c.windDuration),("drift",c.drift),("windY",c.windY)] {
                    XCTAssertEqual(value,n(r,key),accuracy:1e-10)
                }
            }
            graph.dispose();XCTAssertEqual(runtime.activeCount,0);runtime.dispose()
        }
    }
    func testOriginalDuplicateFontDrawsDefaultCloudsAndDelayedBouncesAreOwned()throws {
        let runtime=NativeSourceAnimationRuntime(wallOriginMilliseconds:0)
        var draws=0
        let graph=try NativeEndgameHintSourceGraph(message:"Stack it!",width:390,height:844,
            scheduler:NativeNoMovesValueScheduler(runtime),current:{true},random:{draws+=1;return 0.5})
        defer{graph.dispose();runtime.dispose()}
        XCTAssertEqual(draws,30+2*(9+1));XCTAssertEqual(graph.letters.count,9);XCTAssertEqual(graph.clouds.count,5)
        XCTAssertEqual(graph.letters[0].size,66.6);XCTAssertEqual(graph.letters[1].size,61.4)
        XCTAssertEqual(graph.letters[5].size,64);XCTAssertEqual(graph.tilt,0)
        XCTAssertEqual(graph.clouds[0].delay,0);XCTAssertEqual(graph.clouds[1].delay,0.06)
        XCTAssertEqual(graph.clouds[0].windDuration,1.032,accuracy:1e-12)
        for t in stride(from:0,through:2000,by:10){runtime.deliver(wallMilliseconds:Double(t))}
        XCTAssertEqual(draws,30+2*(9+1)+9*3)
        XCTAssertTrue(graph.glyphs.allSatisfy{$0.alpha==1 && $0.scale>=1})
        XCTAssertEqual(runtime.activeCount,9,"Only visible caption bounces remain after finite original clouds")
        graph.dispose();graph.dispose();XCTAssertEqual(runtime.activeCount,0)
        let stopped=draws;runtime.deliver(wallMilliseconds:2010);XCTAssertEqual(draws,stopped)
    }
    func testIneligibleAndRetiredCoordinatorNeverPreparesAssetsOrSchedulesWork() {
        let service=NativeSourceAnimationClockService(wallOriginMilliseconds:0,sourceWallMillisecondsNow:{0})
        let host=UIView(frame:.init(x:0,y:0,width:390,height:844))
        let owner=NativeEndgameHintCoordinator(host:host,root:NativeTestResources.root,service:service,current:{_ in true})
        owner.update(eligible:false,generation:1);owner.interact();owner.reset()
        XCTAssertEqual(owner.preparationCount,0);XCTAssertEqual(owner.pendingTimers,0);XCTAssertNil(owner.presentation)
        XCTAssertEqual(service.activeParticipantCount,0);XCTAssertFalse(service.hasActiveClock)
        owner.dispose();owner.update(eligible:true,generation:2)
        XCTAssertEqual(owner.preparationCount,0);XCTAssertEqual(owner.pendingTimers,0);service.dispose()
    }
    func testCurrentGenerationRetirementCancelsEveryRootAndStopsMath()throws {
        let runtime=NativeSourceAnimationRuntime(wallOriginMilliseconds:0);var current=true,draws=0
        let graph=try NativeEndgameHintSourceGraph(message:"Stack it!",width:390,height:844,
            scheduler:NativeNoMovesValueScheduler(runtime),current:{current},random:{draws+=1;return 0.5})
        current=false;runtime.deliver(wallMilliseconds:10)
        XCTAssertEqual(runtime.activeCount,0);let stopped=draws
        runtime.deliver(wallMilliseconds:20);graph.beginExit();XCTAssertEqual(draws,stopped)
        graph.dispose();runtime.dispose()
    }
    func testReentrantRandomClosesPartialCloudConstructionWithoutLeakingRoots() {
        let runtime=NativeSourceAnimationRuntime(wallOriginMilliseconds:0);var current=true,draws=0
        XCTAssertThrowsError(try NativeEndgameHintSourceGraph(message:"Stack it!",width:390,height:844,
            scheduler:NativeNoMovesValueScheduler(runtime),current:{current},random:{draws+=1;if draws==10{current=false};return 0.5}))
        XCTAssertEqual(draws,10);XCTAssertEqual(runtime.activeCount,0);runtime.dispose()
    }
    func testCapturedExitCompletesOnceAtOriginalFastExitAndRetainsNoBounces()throws {
        let runtime=NativeSourceAnimationRuntime(wallOriginMilliseconds:0);var finished=0,draws=0
        let graph=try NativeEndgameHintSourceGraph(message:"Stack it!",width:390,height:844,
            scheduler:NativeNoMovesValueScheduler(runtime),current:{true},random:{draws+=1;return 0.5})
        graph.onFinished={_ in finished+=1}
        for t in stride(from:0,through:2000,by:10){runtime.deliver(wallMilliseconds:Double(t))}
        let before=draws;graph.beginExit();graph.beginExit();XCTAssertEqual(draws,before+9)
        for t in stride(from:2010,through:2210,by:10){runtime.deliver(wallMilliseconds:Double(t))}
        XCTAssertEqual(finished,0)
        for t in stride(from:2220,through:2300,by:10){runtime.deliver(wallMilliseconds:Double(t))}
        XCTAssertEqual(finished,1);XCTAssertTrue(graph.glyphs.allSatisfy{$0.scale==0 && $0.alpha==0})
        XCTAssertEqual(runtime.activeCount,0);graph.dispose();runtime.dispose()
    }
